CREATE TABLE supplier_invoices (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,invoice_code VARCHAR(30) NOT NULL,vendor_id BIGINT UNSIGNED NOT NULL,project_id BIGINT UNSIGNED NOT NULL,invoice_number VARCHAR(100) NOT NULL,invoice_date DATE NOT NULL,due_date DATE NULL,reference VARCHAR(190) NULL,notes TEXT NULL,total_amount DECIMAL(18,2) NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',vendor_code_snapshot VARCHAR(30) NULL,vendor_name_snapshot VARCHAR(190) NULL,project_code_snapshot VARCHAR(30) NULL,project_name_snapshot VARCHAR(190) NULL,created_by BIGINT UNSIGNED NOT NULL,approved_at DATETIME NULL,approved_by BIGINT UNSIGNED NULL,cancelled_at DATETIME NULL,cancelled_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_supplier_invoices_code(invoice_code),UNIQUE KEY uq_supplier_invoices_vendor_number(vendor_id,invoice_number),KEY idx_supplier_invoices_project_status_date(project_id,status,invoice_date),KEY idx_supplier_invoices_vendor_status_date(vendor_id,status,invoice_date),KEY idx_supplier_invoices_due_date(due_date),CONSTRAINT fk_supplier_invoices_vendor FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE RESTRICT,CONSTRAINT fk_supplier_invoices_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT,CONSTRAINT fk_supplier_invoices_created_by FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_supplier_invoices_approved_by FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_supplier_invoices_cancelled_by FOREIGN KEY(cancelled_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_supplier_invoices_status CHECK(status IN('draft','approved','cancelled')),CONSTRAINT chk_supplier_invoices_dates CHECK(due_date IS NULL OR due_date>=invoice_date),CONSTRAINT chk_supplier_invoices_audit CHECK((status='draft' AND total_amount IS NULL AND vendor_code_snapshot IS NULL AND vendor_name_snapshot IS NULL AND project_code_snapshot IS NULL AND project_name_snapshot IS NULL AND approved_at IS NULL AND approved_by IS NULL AND cancelled_at IS NULL AND cancelled_by IS NULL) OR(status='approved' AND total_amount>0 AND vendor_code_snapshot IS NOT NULL AND vendor_name_snapshot IS NOT NULL AND project_code_snapshot IS NOT NULL AND project_name_snapshot IS NOT NULL AND approved_at IS NOT NULL AND approved_by IS NOT NULL AND cancelled_at IS NULL AND cancelled_by IS NULL) OR(status='cancelled' AND total_amount IS NULL AND vendor_code_snapshot IS NULL AND vendor_name_snapshot IS NULL AND project_code_snapshot IS NULL AND project_name_snapshot IS NULL AND approved_at IS NULL AND approved_by IS NULL AND cancelled_at IS NOT NULL AND cancelled_by IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
